// relayTestStore opens a fresh Store over a temp file for the relay tables
// (the queueTestStore shape, minus the module registry the relay never reads).
func relayTestStore(t *testing.T) *store.Store {
	t.Helper()
	s, err := store.Open(context.Background(), filepath.Join(t.TempDir(), "relay.db"))
	if err != nil {
		t.Fatalf("store.Open: %v", err)
	}
	t.Cleanup(func() { _ = s.Close() })
	return s
}

// relaySeedPlan is a minimal single-spec request plan (the enqueue input task
// 3.2 hands over verbatim).
func relaySeedPlan() []store.PlanSpec {
	return []store.PlanSpec{
		{
			Method:         "GET",
			URL:            "https://shikimori.one/api/animes/1",
			Headers:        map[string]string{"Accept": "application/json"},
			TimeoutSeconds: 10,
			MinIntervalMS:  250,
		},
	}
}

// relayClaim claims one job back from the store (the only read path 1.1
// exposes) so the tests can assert the inserted row verbatim.
func relayClaim(t *testing.T, s *store.Store) (store.RelayJob, bool) {
	t.Helper()
	job, found, err := s.ClaimOldestRelayJob(context.Background(), "test-principal", time.Now(), time.Now().Add(time.Minute))
	if err != nil {
		t.Fatalf("ClaimOldestRelayJob: %v", err)
	}
	return job, found
}

// assertRelayFlat asserts the row's eligibility is the FLAT cooldown: the
// next-eligible deadline sits one cool past the failure stamp (the explicit-
// cooldown flat shape — doubling would land at 2*cool and fail the window).
// The stamp and the deadline come from two clock reads (the store's failed_at,
// the enrich clock's deadline), so the window tolerates their skew.
func assertRelayFlat(t *testing.T, row store.FailureRow, cool time.Duration) {
	t.Helper()
	diff := row.NextEligibleAt.Sub(row.FailedAt)
	if diff < cool-30*time.Second || diff > cool+30*time.Second {
		t.Fatalf("flat eligibility: next_eligible - failed_at = %v, want ~%v (flat, no doubling)", diff, cool)
	}
}

// relayEnqueueArgs is one Enqueue call's shape (the boundary signature task
// 3.2/5.1 call through).
type relayEnqueueArgs struct {
	plan      []store.PlanSpec
	purpose   string
	rowID     string
	libraryID int64
	pluginID  string
	class     string
	errText   string
}

// TestRelayEnqueue covers the enqueue boundary over a real store: an enrich
// handoff inserts the job and the relayed ledger row with FLAT eligibility,
// a repeat handoff advances the round counter without doubling the cooldown,
// the cool knob is honored verbatim, a stale prior row increments instead of
// resetting, and a search-purpose enqueue inserts the job but leaves the
// ledger untouched (no (row, plugin) pair — D5).
func TestRelayEnqueue(t *testing.T) {
	ctx := context.Background()

	t.Run("enrich_flat_default_cool", func(t *testing.T) {
		s := relayTestStore(t)
		r := NewRelay(s, 0, 0, nil) // zero knobs -> defaults: lease 2m, flat cool 10m
		args := relayEnqueueArgs{
			plan:      relaySeedPlan(),
			purpose:   "enrich",
			rowID:     "itm_1",
			libraryID: 7,
			pluginID:  "shikimori",
			class:     "network",
			errText:   `Get "https://shikimori.one/api/animes/1": dial tcp 1.2.3.4:443: connect: connection refused`,
		}
		if err := r.Enqueue(ctx, args.plan, args.purpose, args.rowID, args.libraryID, args.pluginID, args.class, args.errText); err != nil {
			t.Fatalf("Enqueue: %v", err)
		}
		job, found := relayClaim(t, s)
		if !found {
			t.Fatal("job not claimable after enrich enqueue")
		}
		if job.Purpose != "enrich" || job.RowID != "itm_1" || job.LibraryID != 7 || job.PluginID != "shikimori" {
			t.Fatalf("job fields: purpose=%q row=%q lib=%d plugin=%q", job.Purpose, job.RowID, job.LibraryID, job.PluginID)
		}
		if job.State != "claimed" || job.Consumed {
			// relayClaim itself flips the row to claimed — a successful claim of
			// the just-inserted row IS the pending-row proof; consumed stays false.
			t.Fatalf("job post-claim state: state=%q consumed=%v", job.State, job.Consumed)
		}
		if !reflect.DeepEqual(job.Plan, args.plan) {
			t.Fatalf("plan round-trip: got %+v, want %+v", job.Plan, args.plan)
		}
		rows, err := s.ListFailures(ctx)
		if err != nil {
			t.Fatalf("ListFailures: %v", err)
		}
		if len(rows) != 1 {
			t.Fatalf("ledger rows: got %d, want 1", len(rows))
		}
		row := rows[0]
		if row.ItemID != "itm_1" || row.PluginID != "shikimori" {
			t.Fatalf("ledger key: %s/%s", row.ItemID, row.PluginID)
		}
		if row.Status != "relayed" {
			t.Fatalf("ledger status: got %q, want relayed", row.Status)
		}
		if !strings.HasPrefix(row.Reason, "network: ") || !strings.Contains(row.Reason, "connection refused") {
			t.Fatalf("reason carries class token + error text: %q", row.Reason)
		}
		if row.Attempts != 1 {
			t.Fatalf("first relay round attempts: got %d, want 1", row.Attempts)
		}
		assertRelayFlat(t, row, 10*time.Minute)
	})

	t.Run("repeat_handoff_no_doubling", func(t *testing.T) {
		s := relayTestStore(t)
		r := NewRelay(s, 0, 0, nil)
		for i := 0; i < 2; i++ {
			if err := r.Enqueue(ctx, relaySeedPlan(), "enrich", "itm_2", 7, "shikimori", "network", "dial tcp: i/o timeout"); err != nil {
				t.Fatalf("Enqueue #%d: %v", i+1, err)
			}
		}
		rows, err := s.ListFailures(ctx)
		if err != nil {
			t.Fatalf("ListFailures: %v", err)
		}
		if len(rows) != 1 {
			t.Fatalf("ledger rows: got %d, want 1 (the relayed row upserts, never accumulates)", len(rows))
		}
		if rows[0].Attempts != 2 {
			t.Fatalf("second relay round attempts: got %d, want 2", rows[0].Attempts)
		}
		assertRelayFlat(t, rows[0], 10*time.Minute) // a doubled schedule would read ~20m
	})

	t.Run("custom_cool_knob", func(t *testing.T) {
		s := relayTestStore(t)
		r := NewRelay(s, 0, 3*time.Minute, nil)
		if err := r.Enqueue(ctx, relaySeedPlan(), "enrich", "itm_3", 7, "shikimori", "network", "dial tcp: i/o timeout"); err != nil {
			t.Fatalf("Enqueue: %v", err)
		}
		rows, err := s.ListFailures(ctx)
		if err != nil {
			t.Fatalf("ListFailures: %v", err)
		}
		if len(rows) != 1 {
			t.Fatalf("ledger rows: got %d, want 1", len(rows))
		}
		assertRelayFlat(t, rows[0], 3*time.Minute)
	})

	t.Run("stale_prior_row_increments", func(t *testing.T) {
		s := relayTestStore(t)
		r := NewRelay(s, 0, 0, nil)
		// A lapsed terminal row from an earlier cycle: the increment discipline
		// advances it, it never resets to 1 (the ledger's own precedent).
		if err := s.RecordFailure(ctx, "itm_4", "shikimori", "exhausted", "prior cycle", 3, time.Now().Add(-time.Hour)); err != nil {
			t.Fatalf("seed RecordFailure: %v", err)
		}
		if err := r.Enqueue(ctx, relaySeedPlan(), "enrich", "itm_4", 7, "shikimori", "network", "dial tcp: i/o timeout"); err != nil {
			t.Fatalf("Enqueue: %v", err)
		}
		rows, err := s.ListFailures(ctx)
		if err != nil {
			t.Fatalf("ListFailures: %v", err)
		}
		if len(rows) != 1 || rows[0].Status != "relayed" || rows[0].Attempts != 4 {
			t.Fatalf("relayed row over stale prior: %+v", rows)
		}
	})

	t.Run("search_purpose_no_ledger", func(t *testing.T) {
		s := relayTestStore(t)
		r := NewRelay(s, 0, 0, nil)
		if err := r.Enqueue(ctx, relaySeedPlan(), "search", "", 0, "shikimori", "network", "dial tcp: i/o timeout"); err != nil {
			t.Fatalf("Enqueue: %v", err)
		}
		rows, err := s.ListFailures(ctx)
		if err != nil {
			t.Fatalf("ListFailures: %v", err)
		}
		if len(rows) != 0 {
			t.Fatalf("search enqueue wrote ledger rows: %+v", rows)
		}
		job, found := relayClaim(t, s)
		if !found {
			t.Fatal("search job not claimable after enqueue")
		}
		if job.Purpose != "search" || job.PluginID != "shikimori" {
			t.Fatalf("search job fields: purpose=%q plugin=%q", job.Purpose, job.PluginID)
		}
	})
}

// TestRelayEnqueueRedactsURLs covers redactURLs — the one redaction home
// (D6) — as a unit table over the error-text shapes the fetch seam produces,
// plus the integration pin: a keyed URL handed through Enqueue never lands
// verbatim in the stored ledger reason.
func TestRelayEnqueueRedactsURLs(t *testing.T) {
	t.Run("redactURLs_table", func(t *testing.T) {
		cases := []struct {
			name, in, want string
			forbidden      []string // substrings that must not survive
		}{
			{
				name:      "keyed_query",
				in:        `Get "https://api.themoviedb.org/3/search/movie?api_key=SECRETKEY&query=dune": dial tcp: i/o timeout`,
				want:      `Get "https://api.themoviedb.org/3/search/movie?[redacted]": dial tcp: i/o timeout`,
				forbidden: []string{"SECRETKEY", "query=dune"},
			},
			{
				name:      "userinfo_credentials",
				in:        `post https://user:pass@upstream.example/data failed`,
				want:      `post https://upstream.example/data?[redacted] failed`,
				forbidden: []string{"user:pass"},
			},
			{
				name: "plain_url_untouched",
				in:   `Get "https://shikimori.one/api/animes/1": dial tcp 1.2.3.4:443: connect: connection refused`,
				want: `Get "https://shikimori.one/api/animes/1": dial tcp 1.2.3.4:443: connect: connection refused`,
			},
			{
				name: "no_url",
				in:   "context deadline exceeded",
				want: "context deadline exceeded",
			},
			{
				name:      "multiple_urls",
				in:        "primary https://a.example/x?api_key=K1 then extra https://b.example/y",
				want:      "primary https://a.example/x?[redacted] then extra https://b.example/y",
				forbidden: []string{"api_key=K1"},
			},
			{
				name: "unparseable_token_redacted_wholesale",
				in:   "fetch http://exa[mple.com/x failed",
				want: "fetch [redacted] failed",
			},
		}
		for _, tc := range cases {
			t.Run(tc.name, func(t *testing.T) {
				got := redactURLs(tc.in)
				if got != tc.want {
					t.Fatalf("redactURLs:\n got %q\nwant %q", got, tc.want)
				}
				for _, f := range tc.forbidden {
					if strings.Contains(got, f) {
						t.Fatalf("redactURLs leaked %q: %q", f, got)
					}
				}
			})
		}
	})

	t.Run("stored_reason_redacted", func(t *testing.T) {
		s := relayTestStore(t)
		r := NewRelay(s, 0, 0, nil)
		errText := `Get "https://api.themoviedb.org/3/search/movie?api_key=SECRETKEY&query=dune": dial tcp: i/o timeout`
		if err := r.Enqueue(context.Background(), relaySeedPlan(), "enrich", "itm_9", 7, "tmdb", "network", errText); err != nil {
			t.Fatalf("Enqueue: %v", err)
		}
		rows, err := s.ListFailures(context.Background())
		if err != nil {
			t.Fatalf("ListFailures: %v", err)
		}
		if len(rows) != 1 {
			t.Fatalf("ledger rows: got %d, want 1", len(rows))
		}
		reason := rows[0].Reason
		if !strings.HasPrefix(reason, "network: ") {
			t.Fatalf("reason carries the class token: %q", reason)
		}
		if strings.Contains(reason, "SECRETKEY") || strings.Contains(reason, "api_key=SECRETKEY&query=dune") {
			t.Fatalf("stored reason leaked the keyed URL: %q", reason)
		}
		if !strings.Contains(reason, "api.themoviedb.org/3/search/movie") {
			t.Fatalf("stored reason lost the redacted URL shape: %q", reason)
		}
	})
}

// relayNotifyRecorder returns a library-notify closure collecting the woken
// library ids into dst (the Ingest-done completion wake assertion).
func relayNotifyRecorder(dst *[]int64) func(context.Context, int64) {
	return func(_ context.Context, libraryID int64) { *dst = append(*dst, libraryID) }
}

// relayHandoff runs one full handoff through the Relay surface: Enqueue, then
// Claim for the principal hash — the claimed job (its id is the ingest input)
// comes back or the test fails.
func relayHandoff(t *testing.T, r *Relay, purpose, rowID string, libraryID int64, pluginID, principal string) store.RelayJob {
	t.Helper()
	if err := r.Enqueue(context.Background(), relaySeedPlan(), purpose, rowID, libraryID, pluginID, "network", "dial tcp: i/o timeout"); err != nil {
		t.Fatalf("Enqueue: %v", err)
	}
	job, found, err := r.Claim(context.Background(), principal)
	if err != nil {
		t.Fatalf("Claim: %v", err)
	}
	if !found {
		t.Fatal("Claim: nothing claimable right after the enqueue")
	}
	return job
}

// relayDoneResult is a canned successful client response for the seed plan's
// URL (the shape a live claimant posts through 4.2).
func relayDoneResult() store.RelayResult {
	return store.RelayResult{
		HTTPStatus: 200,
		Headers:    map[string]string{"Content-Type": "application/json"},
		Body:       []byte(`{"id":1,"name":"frieren"}`),
	}
}

// TestRelayClaim covers the client-facing claim handout: the descriptor rides
// the store's one conditional UPDATE with the claim stamped for the calling
// principal and the lease from the configured TTL; the empty queue is
// not-found; claims drain oldest-first; and a lapsed lease is re-claimable by
// another principal (lazy expiry — no sweeper).
func TestRelayClaim(t *testing.T) {
	ctx := context.Background()

	t.Run("descriptor_stamped_with_principal_and_ttl", func(t *testing.T) {
		s := relayTestStore(t)
		r := NewRelay(s, time.Minute, 0, nil)
		if err := r.Enqueue(ctx, relaySeedPlan(), "enrich", "itm_1", 7, "shikimori", "network", "dial tcp: i/o timeout"); err != nil {
			t.Fatalf("Enqueue: %v", err)
		}
		job, found, err := r.Claim(ctx, "principal-a")
		if err != nil || !found {
			t.Fatalf("Claim: found=%v err=%v", found, err)
		}
		if job.ID == 0 || job.Purpose != "enrich" || job.RowID != "itm_1" || job.LibraryID != 7 || job.PluginID != "shikimori" {
			t.Fatalf("descriptor fields: %+v", job)
		}
		if !reflect.DeepEqual(job.Plan, relaySeedPlan()) {
			t.Fatalf("descriptor plan: got %+v", job.Plan)
		}
		if job.State != "claimed" || job.ClaimPrincipalHash != "principal-a" {
			t.Fatalf("claim stamps: state=%q hash=%q", job.State, job.ClaimPrincipalHash)
		}
		if job.ClaimedAt.IsZero() {
			t.Fatal("claimed_at not stamped")
		}
		// lease_until - claimed_at is the configured TTL (both stamps ride the
		// same clock read; the window absorbs the RFC3339Nano round-trip).
		if lease := job.LeaseUntil.Sub(job.ClaimedAt); lease < time.Minute-2*time.Second || lease > time.Minute+2*time.Second {
			t.Fatalf("lease window: got %v, want ~%v", lease, time.Minute)
		}
	})

	t.Run("empty_queue_not_found", func(t *testing.T) {
		s := relayTestStore(t)
		r := NewRelay(s, 0, 0, nil)
		job, found, err := r.Claim(ctx, "principal-a")
		if err != nil || found {
			t.Fatalf("Claim on empty queue: found=%v err=%v", found, err)
		}
		if job.ID != 0 || job.State != "" {
			t.Fatalf("not-found must be the zero job: %+v", job)
		}
	})

	t.Run("oldest_first_then_drained", func(t *testing.T) {
		s := relayTestStore(t)
		r := NewRelay(s, 0, 0, nil)
		if err := r.Enqueue(ctx, relaySeedPlan(), "enrich", "itm_1", 7, "shikimori", "network", "dial tcp: i/o timeout"); err != nil {
			t.Fatalf("Enqueue #1: %v", err)
		}
		if err := r.Enqueue(ctx, relaySeedPlan(), "enrich", "itm_2", 7, "shikimori", "network", "dial tcp: i/o timeout"); err != nil {
			t.Fatalf("Enqueue #2: %v", err)
		}
		first, found, err := r.Claim(ctx, "principal-a")
		if err != nil || !found {
			t.Fatalf("Claim #1: found=%v err=%v", found, err)
		}
		second, found, err := r.Claim(ctx, "principal-b")
		if err != nil || !found {
			t.Fatalf("Claim #2: found=%v err=%v", found, err)
		}
		if first.ID >= second.ID {
			t.Fatalf("claims must drain oldest-first: %d then %d", first.ID, second.ID)
		}
		if first.ClaimPrincipalHash != "principal-a" || second.ClaimPrincipalHash != "principal-b" {
			t.Fatalf("each claim stamped its own principal: %q / %q", first.ClaimPrincipalHash, second.ClaimPrincipalHash)
		}
		if _, found, err := r.Claim(ctx, "principal-a"); err != nil || found {
			t.Fatalf("drained queue must read not-found: found=%v err=%v", found, err)
		}
	})

	t.Run("expired_lease_reclaimed_by_next_principal", func(t *testing.T) {
		s := relayTestStore(t)
		r := NewRelay(s, 25*time.Millisecond, 0, nil) // tiny TTL: expiry is lazy, the next claim's predicate decides
		if err := r.Enqueue(ctx, relaySeedPlan(), "enrich", "itm_1", 7, "shikimori", "network", "dial tcp: i/o timeout"); err != nil {
			t.Fatalf("Enqueue: %v", err)
		}
		abandoned, found, err := r.Claim(ctx, "principal-a")
		if err != nil || !found {
			t.Fatalf("first Claim: found=%v err=%v", found, err)
		}
		time.Sleep(60 * time.Millisecond) // past the 25ms lease: the claim is now stale
		retaken, found, err := r.Claim(ctx, "principal-b")
		if err != nil || !found {
			t.Fatalf("re-claim after expiry: found=%v err=%v", found, err)
		}
		if retaken.ID != abandoned.ID {
			t.Fatalf("re-claim took job %d, want the abandoned %d", retaken.ID, abandoned.ID)
		}
		if retaken.ClaimPrincipalHash != "principal-b" {
			t.Fatalf("re-claim stamped %q, want principal-b", retaken.ClaimPrincipalHash)
		}
		if !retaken.LeaseUntil.After(abandoned.LeaseUntil) {
			t.Fatalf("re-claim did not extend the lease: %v -> %v", abandoned.LeaseUntil, retaken.LeaseUntil)
		}
	})
}

// TestRelayConsult covers the relay cache read: a done, unconsumed,
// plan-matched job hands over its stored response exactly once (the hit
// consumes); a plan mismatch, a non-done state, and a missing job are all
// misses that leave the store untouched (D4 — safe degradation).
func TestRelayConsult(t *testing.T) {
	ctx := context.Background()

	// relayConsultFixture completes one full enrich round to a done state for
	// the pair (itm_1, shikimori) with the given result.
	relayConsultFixture := func(t *testing.T, result store.RelayResult) *Relay {
		t.Helper()
		s := relayTestStore(t)
		r := NewRelay(s, 0, 0, nil)
		job := relayHandoff(t, r, "enrich", "itm_1", 7, "shikimori", "principal-a")
		if err := r.Ingest(ctx, job.ID, "principal-a", result); err != nil {
			t.Fatalf("Ingest: %v", err)
		}
		return r
	}

	t.Run("hit_consumes_stored_response", func(t *testing.T) {
		done := relayDoneResult()
		r := relayConsultFixture(t, done)
		got, ok, err := r.Consult(ctx, "itm_1", "shikimori", relaySeedPlan())
		if err != nil || !ok {
			t.Fatalf("Consult: ok=%v err=%v", ok, err)
		}
		if !reflect.DeepEqual(got, done) {
			t.Fatalf("stored response round-trip: got %+v, want %+v", got, done)
		}
		// The hit consumed the job: the second read of the same plan misses.
		if _, ok, err := r.Consult(ctx, "itm_1", "shikimori", relaySeedPlan()); err != nil || ok {
			t.Fatalf("second Consult must miss (consumed): ok=%v err=%v", ok, err)
		}
	})

	t.Run("plan_mismatch_misses_and_stays_unconsumed", func(t *testing.T) {
		r := relayConsultFixture(t, relayDoneResult())
		drifted := relaySeedPlan()
		drifted[0].URL = "https://shikimori.one/api/animes/1?field=extra" // the document drifted mid-flight
		if got, ok, err := r.Consult(ctx, "itm_1", "shikimori", drifted); err != nil || ok {
			t.Fatalf("mismatched plan must miss: ok=%v err=%v got=%+v", ok, err, got)
		}
		// The stale job was NOT consumed into the miss: the matching plan still hits.
		if _, ok, err := r.Consult(ctx, "itm_1", "shikimori", relaySeedPlan()); err != nil || !ok {
			t.Fatalf("matching plan must still hit after a mismatch: ok=%v err=%v", ok, err)
		}
	})

	t.Run("no_job_is_a_miss", func(t *testing.T) {
		s := relayTestStore(t)
		r := NewRelay(s, 0, 0, nil)
		if got, ok, err := r.Consult(ctx, "itm_1", "shikimori", relaySeedPlan()); err != nil || ok || got.HTTPStatus != 0 {
			t.Fatalf("empty cache must miss: ok=%v err=%v got=%+v", ok, err, got)
		}
	})

	t.Run("pending_job_is_a_miss", func(t *testing.T) {
		s := relayTestStore(t)
		r := NewRelay(s, 0, 0, nil)
		if err := r.Enqueue(ctx, relaySeedPlan(), "enrich", "itm_1", 7, "shikimori", "network", "dial tcp: i/o timeout"); err != nil {
			t.Fatalf("Enqueue: %v", err)
		}
		if _, ok, err := r.Consult(ctx, "itm_1", "shikimori", relaySeedPlan()); err != nil || ok {
			t.Fatalf("pending job must miss: ok=%v err=%v", ok, err)
		}
	})

	t.Run("failed_job_is_a_miss", func(t *testing.T) {
		s := relayTestStore(t)
		r := NewRelay(s, 0, 0, nil)
		job := relayHandoff(t, r, "enrich", "itm_1", 7, "shikimori", "principal-a")
		if err := r.Ingest(ctx, job.ID, "principal-a", store.RelayResult{Error: "client: dial tcp: i/o timeout"}); err != nil {
			t.Fatalf("Ingest: %v", err)
		}
		if _, ok, err := r.Consult(ctx, "itm_1", "shikimori", relaySeedPlan()); err != nil || ok {
			t.Fatalf("failed job must miss: ok=%v err=%v", ok, err)
		}
	})
}

// TestRelayIngest covers the principal-guarded ingestion: a done enrich job
// clears the pair's ledger row and wakes the library; wrong-principal and
// expired-claim posts are refused with the 409 shape (wrapped sql.ErrNoRows)
// and leave the row's claim intact or expired; a failed round increments the
// attempts column and re-arms the FLAT cooldown; search jobs complete without
// touching ledger or notify.
func TestRelayIngest(t *testing.T) {
	ctx := context.Background()

	t.Run("done_enrich_clears_ledger_and_notifies", func(t *testing.T) {
		s := relayTestStore(t)
		var woken []int64
		r := NewRelay(s, 0, 0, relayNotifyRecorder(&woken))
		job := relayHandoff(t, r, "enrich", "itm_1", 7, "shikimori", "principal-a")
		rows, err := s.ListFailures(ctx)
		if err != nil || len(rows) != 1 {
			t.Fatalf("pre-ingest ledger: rows=%d err=%v (the relayed row must exist)", len(rows), err)
		}
		if err := r.Ingest(ctx, job.ID, "principal-a", relayDoneResult()); err != nil {
			t.Fatalf("Ingest: %v", err)
		}
		rows, err = s.ListFailures(ctx)
		if err != nil || len(rows) != 0 {
			t.Fatalf("done must clear the pair's ledger row: rows=%d err=%v", len(rows), err)
		}
		if !reflect.DeepEqual(woken, []int64{7}) {
			t.Fatalf("completion wake: got %v, want [7]", woken)
		}
		// The stored response is now the consult cache for the pair.
		if _, ok, err := r.Consult(ctx, "itm_1", "shikimori", relaySeedPlan()); err != nil || !ok {
			t.Fatalf("done result must be consultable: ok=%v err=%v", ok, err)
		}
	})

	t.Run("wrong_principal_refused_claim_intact", func(t *testing.T) {
		s := relayTestStore(t)
		r := NewRelay(s, 0, 0, nil)
		job := relayHandoff(t, r, "enrich", "itm_1", 7, "shikimori", "principal-a")
		err := r.Ingest(ctx, job.ID, "principal-b", relayDoneResult())
		if !errors.Is(err, sql.ErrNoRows) {
			t.Fatalf("foreign principal must be refused with the 409 shape (wrapped ErrNoRows), got %v", err)
		}
		// The refusal left the claim untouched: the rightful principal still completes.
		if err := r.Ingest(ctx, job.ID, "principal-a", relayDoneResult()); err != nil {
			t.Fatalf("rightful principal must still complete after a refused foreign post: %v", err)
		}
	})

	t.Run("expired_claim_refused_row_reclaimable", func(t *testing.T) {
		s := relayTestStore(t)
		r := NewRelay(s, 25*time.Millisecond, 0, nil)
		job := relayHandoff(t, r, "enrich", "itm_1", 7, "shikimori", "principal-a")
		time.Sleep(60 * time.Millisecond) // the claim lapsed
		err := r.Ingest(ctx, job.ID, "principal-a", relayDoneResult())
		if !errors.Is(err, sql.ErrNoRows) {
			t.Fatalf("expired claim must be refused with the 409 shape (wrapped ErrNoRows), got %v", err)
		}
		// Nothing was ingested: the expired row is back in the claimable pool.
		retaken, found, err := r.Claim(ctx, "principal-b")
		if err != nil || !found || retaken.ID != job.ID {
			t.Fatalf("expired job must be re-claimable: found=%v id=%d/%d err=%v", found, retaken.ID, job.ID, err)
		}
	})

	t.Run("failed_round_increments_attempts_rearms_flat", func(t *testing.T) {
		s := relayTestStore(t)
		r := NewRelay(s, 0, 0, nil)
		job := relayHandoff(t, r, "enrich", "itm_1", 7, "shikimori", "principal-a") // Enqueue wrote attempts=1
		errText := `Get "https://shikimori.one/api/animes/1?api_key=SECRET": connection reset by peer`
		if err := r.Ingest(ctx, job.ID, "principal-a", store.RelayResult{Error: errText}); err != nil {
			t.Fatalf("Ingest: %v", err)
		}
		rows, err := s.ListFailures(ctx)
		if err != nil || len(rows) != 1 {
			t.Fatalf("failed round must upsert the one relayed row: rows=%d err=%v", len(rows), err)
		}
		row := rows[0]
		if row.Status != "relayed" {
			t.Fatalf("round 1 failure must stay relayed, got %q", row.Status)
		}
		if row.Attempts != 2 {
			t.Fatalf("failed round must increment attempts: got %d, want 2", row.Attempts)
		}
		assertRelayFlat(t, row, 10*time.Minute) // re-armed flat, NOT the doubling schedule
		if !strings.HasPrefix(row.Reason, "relay: ") {
			t.Fatalf("failed round reason carries the relay prefix: %q", row.Reason)
		}
		if strings.Contains(row.Reason, "SECRET") {
			t.Fatalf("failed round reason leaked the keyed URL: %q", row.Reason)
		}
	})

	t.Run("search_ingest_completes_without_ledger_or_notify", func(t *testing.T) {
		s := relayTestStore(t)
		var woken []int64
		r := NewRelay(s, 0, 0, relayNotifyRecorder(&woken))
		job := relayHandoff(t, r, "search", "", 0, "shikimori", "principal-a")
		if err := r.Ingest(ctx, job.ID, "principal-a", relayDoneResult()); err != nil {
			t.Fatalf("Ingest: %v", err)
		}
		rows, err := s.ListFailures(ctx)
		if err != nil || len(rows) != 0 {
			t.Fatalf("search ingest must never touch the ledger: rows=%d err=%v", len(rows), err)
		}
		if len(woken) != 0 {
			t.Fatalf("search ingest must never notify: woken=%v", woken)
		}
	})

	t.Run("unknown_job_refused", func(t *testing.T) {
		s := relayTestStore(t)
		r := NewRelay(s, 0, 0, nil)
		if err := r.Ingest(ctx, 424242, "principal-a", relayDoneResult()); !errors.Is(err, sql.ErrNoRows) {
			t.Fatalf("unknown job id must be refused with the 409 shape, got %v", err)
		}
	})
}

// TestRelayIngestThirdFailureLandsExhausted drives three FULL failed relay
// rounds through the public surface and pins the give-up mechanics (D5, ruled
// OQ-3): rounds one and two re-arm the flat relayed cooldown with the attempts
// column incrementing; the third failed round records terminal exhausted
// through the standard terminalCooldown doubling — 56d for the relay's
// attempts walk (Enqueue and Ingest each increment: 1,2 → 3,4 → 5, exhausted
// stores 6 with exhaustedDoublings(5, MaxAttempts 3) = 3 doublings of the 7d
// default) — never the flat 10m again.
func TestRelayIngestThirdFailureLandsExhausted(t *testing.T) {
	ctx := context.Background()
	s := relayTestStore(t)
	r := NewRelay(s, 0, 0, nil)

	const rowID, pluginID = "itm_x", "shikimori"
	var libID int64 = 7
	for round := 1; round <= 3; round++ {
		job := relayHandoff(t, r, "enrich", rowID, libID, pluginID, "principal-a")
		if err := r.Ingest(ctx, job.ID, "principal-a", store.RelayResult{Error: "client: dial tcp: i/o timeout"}); err != nil {
			t.Fatalf("round %d Ingest: %v", round, err)
		}
		rows, err := s.ListFailures(ctx)
		if err != nil {
			t.Fatalf("round %d ListFailures: %v", round, err)
		}
		if len(rows) != 1 {
			t.Fatalf("round %d: the ledger holds ONE upserted row, got %d", round, len(rows))
		}
		row := rows[0]
		diff := row.NextEligibleAt.Sub(row.FailedAt)
		switch round {
		case 1, 2:
			if row.Status != "relayed" {
				t.Fatalf("round %d must stay relayed, got %q", round, row.Status)
			}
			wantAttempts := 2 * round // Enqueue's +1 and Ingest's +1 per round
			if row.Attempts != wantAttempts {
				t.Fatalf("round %d attempts: got %d, want %d", round, row.Attempts, wantAttempts)
			}
			assertRelayFlat(t, row, 10*time.Minute)
		case 3:
			if row.Status != "exhausted" {
				t.Fatalf("third failed round must land exhausted, got %q", row.Status)
			}
			if row.Attempts != 6 {
				t.Fatalf("exhausted attempts: got %d, want 6 (prior 5 + 1)", row.Attempts)
			}
			// The standard doubling for prior 5: 7d << 3 = 56d — order-of-magnitude
			// beyond the flat handoff cool, exactly terminalCooldown's schedule.
			want := 56 * 24 * time.Hour
			if diff < want-30*time.Second || diff > want+30*time.Second {
				t.Fatalf("exhausted eligibility: next_eligible - failed_at = %v, want ~%v (doubling, not the flat 10m)", diff, want)
			}
		}
	}
}
